import { TimeDomain, TimeInput } from '@visx/scale';

import {
  ZOOM_IN_FACTOR,
  ZOOM_OUT_FACTOR,
  getZoomStep,
} from '../../core/functions/zoom.js';

export function getTimeseriesZoomStep(
  initialDomain: Date[],
  currentDomain: Date[],
  zoomState: string,
  cursorXPoint?: number,
  zoomFactor?: number,
) {
  const nextDomain = getDomainForZoom(
    initialDomain,
    currentDomain,
    zoomState === 'zoom-in',
    cursorXPoint,
    zoomFactor,
  );

  const { newDomain, isMinZoom, isMaxZoom } = getZoomStep(
    initialDomain,
    currentDomain,
    nextDomain as number[],
  );

  return { newDomain: newDomain as Date[], isMinZoom, isMaxZoom };
}

/**
 * Generates a new domain for a zoom operation.
 * @param currentDomain - The minimum and maximum date of the current domain.
 * @param pointDate - The date of the point where the mouse is.
 * @param zoomIn - Whether the zoom operation is in or out.
 * @param initialDomain - The initial domain.
 * @param zoomFactor - The factor to multiply the zoom operation with.
 * @returns The new domain.
 */
export const getDomainForZoom = (
  initialDomain: TimeDomain | undefined,
  currentDomain: TimeDomain,
  zoomIn: boolean,
  pointDate: TimeInput | undefined,
  zoomFactor?: number,
) => {
  let zoomInFactor = ZOOM_IN_FACTOR;
  let zoomOutFactor = ZOOM_OUT_FACTOR;

  const [minDate, maxDate] = currentDomain;

  if (zoomFactor) {
    zoomInFactor = zoomFactor;
    zoomOutFactor = (zoomFactor * 10) / 9;
  }

  const { startZoomInDiff, endZoomInDiff, startZoomOutDiff, endZoomOutDiff } =
    calculateZoomDiffs(
      minDate,
      maxDate,
      pointDate,
      zoomInFactor,
      zoomOutFactor,
    );

  // Limit the zoom-in in order not be able to go back when zoom-out
  if (
    zoomIn &&
    (startZoomInDiff > -zoomInFactor * 2 || endZoomInDiff > -zoomInFactor * 2)
  ) {
    return [new Date(minDate), new Date(maxDate)];
  }

  if (zoomIn) {
    const newStart = +minDate - startZoomInDiff;
    const newEnd = +maxDate + endZoomInDiff;

    return Math.floor(newEnd) > Math.floor(newStart)
      ? [new Date(newStart), new Date(newEnd)]
      : [minDate, maxDate];
  }

  const newStart = +minDate + startZoomOutDiff;
  const newEnd = +maxDate - endZoomOutDiff;

  return initialDomain &&
    newStart >= +initialDomain[0] &&
    newEnd <= +initialDomain[1]
    ? [new Date(newStart), new Date(newEnd)]
    : initialDomain ?? [minDate, maxDate];
};

/**
 * Calculates the zoom diffs for the zoom operation taking into
 * account if the mouse is inside the chart.
 */
const calculateZoomDiffs = (
  chartMinDate: TimeInput,
  chartMaxDate: TimeInput,
  pointDate: TimeInput | undefined,
  zoomInFactor: number,
  zoomOutFactor: number,
) => {
  const minDate = pointDate ? pointDate : chartMinDate;
  const maxDate = pointDate ? pointDate : chartMaxDate;

  const startZoomInDiff = (+chartMinDate - +maxDate) * zoomInFactor;
  const endZoomInDiff = (+minDate - +chartMaxDate) * zoomInFactor;

  const startZoomOutDiff = (+chartMinDate - +maxDate) * zoomOutFactor;
  const endZoomOutDiff = (+minDate - +chartMaxDate) * zoomOutFactor;

  return { startZoomInDiff, endZoomInDiff, startZoomOutDiff, endZoomOutDiff };
};
